// TypeScript Version: 4.1

/**
* Rounds a single-precision floating-point number toward zero to `n` digits in base `b`.
*
* @param x - input value
* @param n - number of digits
* @param b - base
* @returns rounded value
*
* @example
* var v = truncbf( 3.14159, 2, 10 );
* // returns 3.140000104904175
*
* @example
* var v = truncbf( 3.14159, 3, 10 );
* // returns 3.1410000324249268
*
* @example
* var v = truncbf( 15.0, -1, 10 );
* // returns 10.0
*
* @example
* var v = truncbf( -3.14159, 2, 10 );
* // returns -3.140000104904175
*
* @example
* var v = truncbf( NaN, 2, 10 );
* // returns NaN
*/
declare function truncbf( x: number, n: number, b: number ): number;


// EXPORTS //

export = truncbf;
